function clamp(val, min, max) {
  return Math.max(min, Math.min(max, val));
}

function normalizeAngle(angle) {
  let a = angle;
  while (a > Math.PI) a -= Math.PI * 2;
  while (a < -Math.PI) a += Math.PI * 2;
  return a;
}

function hexToCss(hex) {
  return '#' + (hex >>> 0).toString(16).padStart(6, '0');
}

function buildLinearRunway({
  id,
  label,
  colorKey,
  colorHex,
  thresholdX,
  thresholdY,
  endX,
  endY,
  width = 28,
  snapRadius = 44,
  isWaterRunway = false,
  allowedClasses = [],
}) {
  const dx = endX - thresholdX;
  const dy = endY - thresholdY;
  const length = Math.hypot(dx, dy);
  const heading = Math.atan2(dy, dx);
  const centerX = (thresholdX + endX) * 0.5;
  const centerY = (thresholdY + endY) * 0.5;
  return {
    id,
    label,
    type: isWaterRunway ? 'water' : 'runway',
    colorKey,
    colorHex,
    colorCss: hexToCss(colorHex),
    isHelipad: false,
    isWaterRunway: Boolean(isWaterRunway),
    thresholdX,
    thresholdY,
    endX,
    endY,
    x: centerX,
    y: centerY,
    centerX,
    centerY,
    width,
    length,
    heading,
    snapRadius,
    allowedClasses: [...allowedClasses],
  };
}

function buildHelipad({
  id,
  label,
  colorKey = 'blue_heli',
  colorHex = 0x38bdf8,
  x,
  y,
  width = 44,
  snapRadius = 40,
  allowedClasses = ['heli_blue'],
}) {
  return {
    id,
    label,
    type: 'helipad',
    colorKey,
    colorHex,
    colorCss: hexToCss(colorHex),
    isHelipad: true,
    isWaterRunway: false,
    thresholdX: x,
    thresholdY: y,
    endX: x,
    endY: y,
    x,
    y,
    centerX: x,
    centerY: y,
    width,
    length: width,
    radius: width * 0.5,
    heading: 0,
    snapRadius,
    allowedClasses: [...allowedClasses],
  };
}

