                <path d="M12.5,4.2 C14.0,5.6 14.0,10.4 12.5,11.8 M14.8,2.0 C17.3,4.5 17.3,11.5 14.8,14.0" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linecap="round"/>
